export function initIntegrationsAdmin(){
 const form=document.querySelector('#institutional-settings-form'),message=document.querySelector('#settings-feedback'),status=document.querySelector('#integration-status');let dirty=false;form.addEventListener('input',()=>dirty=true);
 async function request(data){const response=await fetch('/api/admin/integracoes',data===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),body=await response.json();if(!response.ok)throw Error(body.error||'Não foi possível consultar a configuração.');return body;}
 function el(tag,text){const e=document.createElement(tag);e.textContent=text;return e;}
 async function refresh(){try{const data=await request();if(!dirty)for(const key of ['email','whatsapp','instagram','address','hours'])form.elements[key].value=data.contatos[key]||'';const items=[['Banco de dados','Conectado','Esta consulta foi respondida pelo banco do site.'],['Arquivos',data.arquivos==='configurado'?'Configurado':'Indisponível','Os arquivos são guardados no armazenamento da hospedagem.'],['WhatsApp',data.contatos.whatsapp?'Contato configurado':'Número não informado','Link para conversa. Não há envio automático.'],['E-mail',data.contatos.email?'Contato configurado':'E-mail não informado','Endereço para contato. Não há serviço de disparos.'],['Notificações automáticas','Não configuradas','Exigem serviço e credenciais reais.'],['Agenda e equipe','Gestão interna','O cadastro de profissional não cria uma conta de acesso.']];const root=document.querySelector('#integration-cards');root.replaceChildren();for(const[title,value,description]of items){const card=document.createElement('article');card.className='metric-card';card.append(el('span',title),el('h3',value),el('small',description));root.append(card);}status.textContent='Configuração consultada às '+new Date().toLocaleTimeString('pt-BR');}catch(error){status.textContent=error.message;}}
 document.querySelector('#integration-refresh').onclick=refresh;form.onsubmit=async event=>{event.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('button');button.disabled=true;message.textContent='Salvando…';try{await request(Object.fromEntries(new FormData(form)));dirty=false;message.textContent='Contatos salvos. A página pública consulta esta configuração ao abrir.';await refresh();window.dispatchEvent(new Event('admin-data-updated'));}catch(error){message.textContent=error.message;}finally{button.disabled=false;}};return{refresh};
}
